from rest_framework import viewsets, permissions, serializers
from rest_framework.exceptions import ValidationError
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import ProjectIssue, SprintSchedule
from .serializers import IssueDetailSerializer

class SprintAssignSerializer(serializers.Serializer):
    sprint_id = serializers.PrimaryKeyRelatedField(
        queryset=SprintSchedule.objects.all()
    )

class ProjectIssueViewSet(viewsets.ModelViewSet):
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return ProjectIssue.objects.filter(project__team__members=self.request.user)

    def get_serializer_class(self):
        if self.action == "assign_sprint":
            return SprintAssignSerializer
        return IssueDetailSerializer

    @action(detail=True, methods=["post"])
    def assign_sprint(self, request, pk=None):
        issue = self.get_object()
        serializer = self.get_serializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        sprint = serializer.validated_data["sprint_id"]
        if sprint.project_id != issue.project_id:
            raise ValidationError("Selected sprint does not belong to the target issue's project")
        issue.sprint = sprint
        issue.save()
        return Response({"status": "assigned", "sprint_id": sprint.id})
